+  if (deploymentProfile.name === 'k56-demo') {
+    app.use('/api/term-tests', async (req, res, next) => {
+      try {
+        if (/^\/(?:teacher|writing-grading)(?:\/|$)/.test(req.path)) return next();
+        const body = req.body && typeof req.body === 'object' ? req.body : {};
+        const declaredClass = body.classCode ?? req.query.class ?? req.query.classCode;
+        if (declaredClass !== undefined && String(declaredClass).trim().toUpperCase() !== 'CODEXDEMO56') {
+          return res.status(403).json({ ok: false, error: 'DEMO_CLASS_NOT_ALLOWED', message: 'Bản thử chỉ mở bài cho lớp CODEXDEMO56.' });
+        }
+        const pathSession = req.path.match(/^\/[^/]+\/session\/([0-9a-f-]{36})\/(?:audio|preview)$/i)?.[1];
+        const tokens = [
+          ['attempt', body.attemptToken],
+          ['session', body.examSessionToken || pathSession]
+        ];
+        for (const [kind, token] of tokens) {
+          if (!token || !z.string().uuid().safeParse(token).success) continue;
+          const table = kind === 'attempt' ? 'term_test_attempt' : 'term_test_exam_session';
+          const found = await pool.query(`SELECT course.erp_class_name_snapshot AS class_name
+            FROM assessment.${table} AS attempt
+            JOIN mapping.classroom_course_mapping AS course
+              ON course.erp_course_class_id = attempt.erp_course_class_id
+            WHERE attempt.id = $1::uuid`, [token]);
+          if (found.rowCount !== 1) {
+            return res.status(404).json({ ok: false, error: 'DEMO_ATTEMPT_NOT_FOUND', message: 'Không tìm thấy lượt làm bài của lớp thử.' });
+          }
+          if (String(found.rows[0].class_name || '').trim().toUpperCase() !== 'CODEXDEMO56') {
+            return res.status(403).json({ ok: false, error: 'DEMO_CLASS_NOT_ALLOWED', message: 'Bản thử chỉ mở bài cho lớp CODEXDEMO56.' });
+          }
+        }
+        return next();
